global _start       ; Директива для линкера, показывающая откуда должно начинаться выполнение программы
section .text       ; Начало секции .text, в которой находятся машинные инструкции для процессора
_start:             ; Метка _start - место начала выполнения программы
    mov rax, 60     ; Копирование значения 60 в регистр rax (номер системного вызова, 60 соответствует системному вызову завершения программы)
    mov rdi, 0      ; Копирование значения 0 в регистр rdi (аргумент системного вызова, в данном случае код возврата: 0 соответствует успешному завершению)
    syscall         ; Передача управления ядру ОС, которое выполняет инструкцию из rax с аргументом из rdi, а именно: завершение программы с кодом 0 (успех)
